import React, { useState } from 'react';

interface PhraseGuideProps {
  onBack: () => void;
}

// 형용사별 자연스러운 꼬리(명사/표현) 사전
const adjTails: Record<string, string[]> = {
  '따뜻한': ['하루', '느낌', '무드', '감성', '스타일', '하루의 시작', '분위기', '계절'],
  '포근한': ['느낌', '하루', '감성', '분위기', '무드', '스타일'],
  '말랑한': ['촉감', '느낌', '감성', '하루', '분위기'],
  '단정한': ['룩', '하루', '분위기', '스타일', '실루엣'],
  '시크한': ['무드', '실루엣', '분위기', '룩', '스타일'],
  '여유로운': ['하루', '분위기', '느낌', '감성', '시간'],
  '부드러운': ['촉감', '느낌', '분위기', '감성', '착용감'],
  '빈티지한': ['감성', '무드', '스타일', '분위기'],
  '감각적인': ['컬러', '하루', '분위기', '감성', '스타일'],
  '차분한': ['느낌', '분위기', '하루', '감성', '무드'],
  '스포티한': ['룩', '무드', '스타일', '감성'],
  '톡톡한': ['포인트', '느낌', '감성', '무드'],
  '유연한': ['실루엣', '느낌', '분위기', '감성'],
  '가벼운': ['착용감', '느낌', '하루', '분위기'],
  '세련된': ['분위기', '룩', '감성', '스타일'],
  '화사한': ['컬러', '느낌', '하루', '분위기', '감성'],
  '내추럴한': ['무드', '분위기', '감성', '스타일'],
  '도톰한': ['촉감', '느낌', '감성', '분위기'],
  '날렵한': ['실루엣', '분위기', '무드'],
  '소프트한': ['느낌', '감성', '분위기', '착용감'],
  '모던한': ['무드', '분위기', '스타일', '감성'],
  '트렌디한': ['룩', '감성', '분위기', '스타일'],
  '깔끔한': ['룩', '분위기', '스타일', '감성'],
  '귀여운': ['포인트', '분위기', '감성', '룩'],
  '클래식한': ['무드', '분위기', '스타일', '감성'],
  '로맨틱한': ['무드', '분위기', '감성', '하루'],
  '활동적인': ['하루', '룩', '분위기', '감성'],
  '실용적인': ['룩', '감성', '분위기', '스타일'],
  '사랑스러운': ['분위기', '감성', '하루', '포인트'],
  '힙한': ['무드', '룩', '감성', '분위기'],
  '청량한': ['느낌', '하루', '분위기', '감성'],
  '꾸안꾸': ['감성', '스타일', '분위기', '룩'],
  '데일리필수': ['아이템', '룩', '스타일'],
  '데일리픽': ['아이템', '룩', '스타일'],
};

const adjectives = Object.keys(adjTails);

const situations = [
  '출근길에', '약속 있는 날', '하루 종일', '늦잠 잔 날', '퇴근 후', '주말마다', 
  '비 오는 날', '날씨 애매한 날', '기분 전환할 때', '첫 만남에', '계절 바뀔 때', 
  '사진 찍는 날', '날이 쌀쌀해질 때', '소풍 가는 날', '데이트할 때', 
  '옷 고르기 귀찮을 때', '기본템 찾을 때', '매일 입고 싶을 때', '여행 갈 때', 
  '편하게 입고 싶을 때'
];

const templates = {
  feeling: [
    '{adjTail}',
    '{adjTail} 가득',
    '{adjTail} 연출',
    '{adjTail} 무드',
    '{adjTail} 감성',
    '{adjTail} 분위기',
    '{adjTail} 포인트',
    '{adjTail} 컬러',
    '{adjTail} 조합',
    '{adjTail} 마무리',
  ],
  situation: [
    '{situation} {adjTail}',
    '{adjTail} {situation}',
    '{situation}엔 {adjTail}',
    '{adjTail} {situation}룩',
    '{adjTail} {situation} 코디',
    '{situation}에 {adjTail} 추천',
    '{situation}에 {adjTail} 감성',
    '{situation}에 {adjTail} 무드',
    '{situation}에 {adjTail} 포인트',
  ],
  benefit: [
    '{adjTail} 활용',
    '{adjTail} 추천템',
    '{adjTail} 스타일링',
    '{adjTail} 완성',
    '{adjTail} 입기 좋은 날',
    '{adjTail} 실용템',
    '{adjTail} 데일리룩',
    '{adjTail}로 핏 완성',
    '{adjTail}로 분위기 업',
    '{adjTail}로 스타일링',
  ]
};

function getRandomType(): 'feeling' | 'situation' | 'benefit' {
  const types = ['feeling', 'situation', 'benefit'] as const;
  return types[Math.floor(Math.random() * types.length)];
}

function makeAdjTailPhrase(adj: string) {
  const tails = adjTails[adj] || [];
  if (tails.length === 0) return '';
  const tail = tails[Math.floor(Math.random() * tails.length)];
  if (adj.endsWith('한') || adj.endsWith('적인')) {
    return `${adj} ${tail}`;
  }
  return `${adj}${tail}`;
}

// 의미상 자연스러운 위치에 (줄바꿈) 삽입
function insertLineBreak(phrase: string): string {
  const breakWords = ['룩', '하루', '무드', '감성', '분위기', '추천템', '코디', '포인트', '컬러', '아이템', '준비', '시간', '시작', '활용', '완성', '연출', '가득', '마무리'];
  for (const word of breakWords) {
    const idx = phrase.indexOf(word);
    if (idx > 0 && idx < phrase.length - word.length) {
      return phrase.slice(0, idx + word.length) + ' (줄바꿈) ' + phrase.slice(idx + word.length);
    }
  }
  return phrase;
}

function generateTypedPhrases(type: 'feeling' | 'situation' | 'benefit', adjectives: string[], situations: string[], count: number): string[] {
  const phrases: string[] = [];
  let tryCount = 0;
  while (phrases.length < count && tryCount < 100) {
    tryCount++;
    const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
    const situation = situations[Math.floor(Math.random() * situations.length)];
    const adjTail = makeAdjTailPhrase(adj);
    if (!adjTail) continue;
    const templateArr = templates[type];
    const template = templateArr[Math.floor(Math.random() * templateArr.length)];
    let phrase = template
      .replace('{adjTail}', adjTail)
      .replace('{situation}', situation);
    if (
      phrase.trim().split(' ').length > 1 &&
      !phrases.includes(phrase) &&
      !/([가-힣]+한)\1/.test(phrase) &&
      !phrase.includes('하게하게') &&
      !phrase.includes('적인하게') &&
      !phrase.includes('소프트한 느낌') &&
      !phrase.includes('실용적인하게')
    ) {
      phrases.push(insertLineBreak(phrase));
    }
  }
  return phrases;
}

const PhraseGuide: React.FC<PhraseGuideProps> = ({ onBack }) => {
  const [selectedBannerType, setSelectedBannerType] = useState<string>('');
  const [mypageLineCount, setMypageLineCount] = useState<1 | 2>(1);
  const [generated, setGenerated] = useState<{
    feeling: string[];
    situation: string[];
    benefit: string[];
  }>({ feeling: [], situation: [], benefit: [] });
  const [isGenerating, setIsGenerating] = useState(false);

  const bannerTypes = [
    { id: 'mypage', name: '마이페이지', maxLength: 13, lines: 2 },
    { id: 'banner', name: '띠배너', maxLength: 20, lines: 1 },
    { id: 'other', name: '기타', maxLength: 13, lines: 2 }
  ];

  const generatePhrases = () => {
    if (!selectedBannerType) {
      alert('배너 타입을 선택해주세요.');
      return;
    }
    setIsGenerating(true);
    setTimeout(() => {
      setGenerated({
        feeling: generateTypedPhrases('feeling', adjectives, situations, 4),
        situation: generateTypedPhrases('situation', adjectives, situations, 4),
        benefit: generateTypedPhrases('benefit', adjectives, situations, 4),
      });
      setIsGenerating(false);
    }, 800);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text.replace(/\n/g, ' '));
    alert('클립보드에 복사되었습니다!');
  };

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 홈으로
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            문구 추천
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            배너 타입 선택
          </h3>
          <p style={{ color: '#64748b', fontSize: '1rem', marginBottom: '15px' }}>
            배너 타입에 따라 문구 길이가 자동으로 조정됩니다.
          </p>
          <div style={{ display: 'flex', gap: '12px', marginBottom: '10px' }}>
            {bannerTypes.map((type) => (
              <button
                key={type.id}
                className={`btn btn-secondary${selectedBannerType === type.id ? ' selected' : ''}`}
                style={{ fontWeight: 600, borderRadius: '18px', padding: '8px 22px', fontSize: '1rem', border: selectedBannerType === type.id ? '2px solid #3b82f6' : undefined, background: selectedBannerType === type.id ? '#3b82f6' : undefined, color: selectedBannerType === type.id ? '#fff' : undefined }}
                onClick={() => setSelectedBannerType(type.id)}
              >
                {type.name}
                <span style={{ fontSize: '0.9rem', marginLeft: 8, color: '#64748b', fontWeight: 400 }}>
                  {type.lines === 1 ? `${type.maxLength}자 이하` : `${type.maxLength}자 이하 ${type.lines}줄`}
                </span>
              </button>
            ))}
          </div>
          {selectedBannerType === 'mypage' && (
            <div style={{ marginTop: '10px', display: 'flex', gap: '10px', alignItems: 'center' }}>
              <span style={{ color: '#64748b', fontSize: '0.98rem' }}>줄 수 선택:</span>
              <button
                className={`btn btn-secondary${mypageLineCount === 1 ? ' selected' : ''}`}
                style={{ fontWeight: 600, borderRadius: '14px', padding: '5px 18px', fontSize: '0.98rem', border: mypageLineCount === 1 ? '2px solid #3b82f6' : undefined, background: mypageLineCount === 1 ? '#3b82f6' : undefined, color: mypageLineCount === 1 ? '#fff' : undefined }}
                onClick={() => setMypageLineCount(1)}
              >
                1줄
              </button>
              <button
                className={`btn btn-secondary${mypageLineCount === 2 ? ' selected' : ''}`}
                style={{ fontWeight: 600, borderRadius: '14px', padding: '5px 18px', fontSize: '0.98rem', border: mypageLineCount === 2 ? '2px solid #3b82f6' : undefined, background: mypageLineCount === 2 ? '#3b82f6' : undefined, color: mypageLineCount === 2 ? '#fff' : undefined }}
                onClick={() => setMypageLineCount(2)}
              >
                2줄
              </button>
            </div>
          )}
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            문구 생성
          </h3>
          <p style={{ color: '#64748b', fontSize: '1rem', marginBottom: '15px' }}>
            선택한 배너 타입에 맞는 자연스럽고 감각적인 문구를 생성합니다.
          </p>
          <button 
            className="btn" 
            style={{ fontSize: '1.1rem', padding: '12px 32px', background: '#3b82f6', color: 'white', fontWeight: 600, borderRadius: 8 }}
            onClick={generatePhrases}
            disabled={!selectedBannerType || isGenerating}
          >
            {isGenerating ? '생성 중...' : '문구 생성하기'}
          </button>
        </div>

        {(generated.feeling.length > 0 || generated.situation.length > 0 || generated.benefit.length > 0) && (
          <div className="mb-20">
            <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>생성된 문구</h3>
            <div className="grid" style={{ gridTemplateColumns: '1fr 1fr 1fr', gap: '18px' }}>
              <div>
                <h4 style={{ color: '#3b82f6', fontWeight: 700, marginBottom: 10 }}>느낌 중심</h4>
                {generated.feeling.map((phrase, idx) => (
                  <div key={idx} className="card" style={{ padding: '14px', marginBottom: '10px', background: '#f8fafc', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
                    <div style={{ fontSize: '1.05rem', color: '#1e293b', fontWeight: 500, marginBottom: '8px', whiteSpace: 'pre-line' }}>{phrase}</div>
                    <button className="btn btn-secondary" style={{ fontSize: '0.9rem', padding: '6px 14px', alignSelf: 'flex-end' }} onClick={() => copyToClipboard(phrase)}>
                      복사
                    </button>
                  </div>
                ))}
              </div>
              <div>
                <h4 style={{ color: '#059669', fontWeight: 700, marginBottom: 10 }}>상황 중심</h4>
                {generated.situation.map((phrase, idx) => (
                  <div key={idx} className="card" style={{ padding: '14px', marginBottom: '10px', background: '#f8fafc', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
                    <div style={{ fontSize: '1.05rem', color: '#1e293b', fontWeight: 500, marginBottom: '8px', whiteSpace: 'pre-line' }}>{phrase}</div>
                    <button className="btn btn-secondary" style={{ fontSize: '0.9rem', padding: '6px 14px', alignSelf: 'flex-end' }} onClick={() => copyToClipboard(phrase)}>
                      복사
                    </button>
                  </div>
                ))}
              </div>
              <div>
                <h4 style={{ color: '#f59e42', fontWeight: 700, marginBottom: 10 }}>혜택 강조형</h4>
                {generated.benefit.map((phrase, idx) => (
                  <div key={idx} className="card" style={{ padding: '14px', marginBottom: '10px', background: '#f8fafc', display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
                    <div style={{ fontSize: '1.05rem', color: '#1e293b', fontWeight: 500, marginBottom: '8px', whiteSpace: 'pre-line' }}>{phrase}</div>
                    <button className="btn btn-secondary" style={{ fontSize: '0.9rem', padding: '6px 14px', alignSelf: 'flex-end' }} onClick={() => copyToClipboard(phrase)}>
                      복사
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>참고 키워드</h3>
          <div className="grid" style={{ gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div>
              <h4 style={{ fontSize: '1rem', marginBottom: '8px', color: '#3b82f6' }}>형용사</h4>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '7px' }}>
                {adjectives.map((adj, index) => (
                  <span key={index} style={{ background: '#e0e7ef', color: '#2563eb', borderRadius: '12px', padding: '4px 12px', fontSize: '0.95rem', fontWeight: 500 }}>{adj}</span>
                ))}
              </div>
            </div>
            <div>
              <h4 style={{ fontSize: '1rem', marginBottom: '8px', color: '#3b82f6' }}>상황</h4>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '7px' }}>
                {situations.map((sit, index) => (
                  <span key={index} style={{ background: '#e0e7ef', color: '#059669', borderRadius: '12px', padding: '4px 12px', fontSize: '0.95rem', fontWeight: 500 }}>{sit}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PhraseGuide;
